_A3 = [("Hintayin natin ang pasyente bago tayo umalis.", "Let us wait for the patient before we leave.", "ang pasyente"), ("Saan ko ito dadalhin?", "Where will I bring this?", "ito"), ("Tawagin mo si Berto sa kabilang bahay para matulungan ka niya.", "Call Berto in the next house so he can help you.", "si Berto"), ("Tanungin mo ang empleyado kung ano ang benepisyo ng Philhealth.", "Ask the employee what the benefits are in Philhealth.", "ang empleyado"), ("Dalhin mo si Lolo sa ospital ngayon din.", "Take Grandpa to the hospital right now.", "si Lolo"), ("Kunin mo ang Philhealth ID niya.", "Get his or her Philhealth ID.", "ang Philhealth ID niya")]
_A4 = [("Huwag mong gamitin ang Philhealth card mo.", "Don’t use your Philhealth card.", "gamitin", "infinitive"), ("Basahin mo ang mga direksiyon dito sa papel na ito.", "Read the directions here on this paper.", "basahin", "infinitive"), ("Inaalam ni Lola ang mga benepisyo niya sa Philhealth.", "Grandma is learning about her Philhealth benefits.", "inaalam", "present"), ("Utangin mo muna ang pambayad sa ospital ni Aling Felisa.", "Borrow the money for Aling Felisa’s hospitalization expenses first.", "utangin", "infinitive"), ("Sasagutin ng doktor ang mga tanong ninyo mamayang hapon.", "The doctor will answer your questions later this afternoon.", "sasagutin", "future"), ("Sasabihin ko sa nars ang mga sintomas ng sakit niya.", "I will tell the nurse the symptoms of his or her illness.", "sasabihin", "future")]
L5 = lesson(
    "C15 L3 · From object focus to doer focus; finding objects and tenses",
    "Binili ni Lourdes ang gamot · Hintayin natin ang pasyente · Inaalam ni Lola ang mga benepisyo",
    requires=[],
    cards=[
        card("Activity 2: object focus to doer focus", "Translate the sentences, then change the object-focus verb into a doer-focus verb. Pattern: verb, doer (Set 2 pronoun or marker), direct object (Set 1 pronoun or marker), rest of sentence. The book gives the first example; the doer-focus versions for items 1 to 4 are my key. In the book’s table the doer of items 3 and 4 is bracketed (Lito, Nanay).", examples=passage([(a, b) for a, b, c in _A2])),
        card("Activity 2: the doer-focus versions (my key)", "", tables=[table(["Object focus", "Doer focus"], [[a, c] for a, b, c in _A2], say=[])]),
        card("Activity 3: direct objects and translations (the book’s key)", "Underline the direct objects of the in/hin/nin verbs, then translate. The objects are: 1. ang pasyente 2. ito 3. si Berto 4. ang empleyado 5. si Lolo 6. ang Philhealth ID niya (my underlining key).", examples=passage([(a, b) for a, b, c in _A3])),
        card("Activity 4: verbs, tenses and translations (the book’s key)", "Circle the in/hin/nin verbs, identify their tense, underline the direct objects and translate. Key: 1. Infinitive 2. Infinitive 3. Present 4. Infinitive 5. Future 6. Future.", examples=passage([(a, b) for a, b, c, d in _A4])),
    ],
    exercises=uniq(
        tr_q([(a, b) for a, b, c in _A2]) + rev_q([(a, b) for a, b, c in _A2]) + tr_q([(a, b) for a, b, c in _A3]) + rev_q([(a, b) for a, b, c in _A3]) + tr_q([(a, b) for a, b, c, d in _A4]) + rev_q([(a, b) for a, b, c, d in _A4])
        + [M(f"What is the direct object in: {a}", c, dd([x[2] for x in _A3], c), c + ".") for a, b, c in _A3]
        + [M(f"What is the tense of the in/hin/nin verb in: {a}", d, dd(["infinitive", "past", "present", "future"], d), d + ".") for a, b, c, d in _A4]
        + [M(f"Which is the in/hin/nin verb in: {a}", c, dd([x[2] for x in _A4], c), c + ".") for a, b, c, d in _A4]
        + [M(f"What is the doer-focus version of: {a}", c, dd([x[2] for x in _A2], c), c) for a, b, c in _A2[1:]]
        + [F(a.replace(c, "___", 1), c, dd([x[2] for x in _A4], c), b) for a, b, c, d in _A4 if a.count(c) == 1]
    ),
)

