_A7 = [("Tanong sa PhilHealth ni Jarius Bondoc.", "A question to PhilHealth, by Jarius Bondoc."), ("May nag-email sa akin tungkol sa medicare coverage ng OFWs.", "Someone emailed me about the medicare coverage of OFWs."), ("Mrs. Josephine Dasalla, Hongkong. Nabasa ko ang kolum ninyo tungkol sa Philhealth.", "Mrs. Josephine Dasalla, Hong Kong. I read your column about Philhealth."), ("Para sa aking legal dependents sa Pilipinas, puwede ba akong mag-member kahit nandito ako sa HK? Papaano?", "For my legal dependents in the Philippines, can I become a member even though I am here in HK? How?"), ("Ipinasagot ko ang mga tanong kay Ms. Linda Laureta, Philhealth manager for corporate communications.", "I had the questions answered by Ms. Linda Laureta, Philhealth manager for corporate communications."), ("Sabi niya, baka ang asawa ni Mrs. Dasalla ay member ng Philhealth, ipagpatuloy na lang ang contributions.", "She said that maybe Mrs. Dasalla’s husband is a Philhealth member, so just continue the contributions."), ("Sakop na ni Mrs. Dasalla at legal dependents nila.", "Mrs. Dasalla and their legal dependents are already covered."), ("Kung hindi naman, puwede niyang pasalihin ang asawa o anak na mayor de edad pero walang asawa, sila naman ni Mrs. Dasalla ang lalabas na dependents.", "If not, she can have her husband or an adult child who is unmarried join, and they and Mrs. Dasalla will come out as dependents."), ("Sakop silang lahat.", "All of them are covered.")]
