        + [M("What is the general rule for using the benefits?", "three months of contributions within six months before hospitalization", ["one payment only", "twelve months of contributions", "no contributions"], "tatlong buwang hulog."), M("If you pay January, February and March, when can you use the benefits?", "in April", ["in January", "in March", "in June"], "by April."), M("Is there an automatic deduction at hospitals abroad?", "no", ["yes", "only in Asia", "only for OFWs"], "hindi automatic."), M("What do you do first if you get sick overseas?", "pay the bill yourself", ["call Manila", "wait", "go home"], "tayo muna ang magbabayad."), M("What do you then submit to Philhealth?", "a medical certificate and official receipts", ["only a letter", "a passport", "a photo"], "medical certificate."), M("What does the medical certificate state?", "the illness, where confined and for how many days", ["the price of the flight", "the hotel", "the airline"], "pagkakasakit, saan, ilang araw."), M("Where do senior citizens go to register?", "the Office of Senior Citizen’s Affairs (OSCA)", ["the airport", "the bank", "the police station"], "OSCA."), M("What form do they fill up?", "the Member’s Registration Form", ["a tax form", "a visa form", "a school form"], "Member’s Registration Form."), M("What does Philhealth give after registration?", "a member data record", ["a car", "a medal", "a ticket"], "member data record."), M("Who can go if the senior is too sick?", "an authorized representative", ["nobody", "the mayor", "a stranger"], "authorized representative."), M("What did R.A. 10606 do?", "it made applying for membership easier", ["it closed Philhealth", "it raised the fees", "it banned OFWs"], "pinadali."), M("Which documents are no longer required?", "birth certificate and marriage contract", ["a passport", "a photo", "a medical certificate"], "hindi na hinihingi.")]
        + [F("Dapat meron kang tatlong buwang ___ sa loob ng anim na buwan. (contribution)", "hulog", ["gastos", "proseso"], "hulog."), F("Tayo muna ang magbabayad ng ating ___. (billing)", "billing", ["receipt", "form"], "billing."), F("Ibibigay din natin ang official ___. (receipt)", "receipt", ["billing", "form"], "receipt."), F("Wala na tayong kailangang ___. (requirements)", "requirements", ["hospital", "senior"], "requirements.")]
