# ------------------------------------------------------------------ 8 activity 10, speaking, glossary
_L10A = [("Question", "Magandang gabi, Doc! Eto po ang katanungan, ano. OFW siya for almost walong taon. Puwede ko po bang gamitin sa mother ko ang PhilHealth ko? Hindi ko pa po nagagamit ’yon.", "Good evening, Doc! Here is the question. She has been an OFW for almost eight years. Can I use my PhilHealth for my mother? I have not used it yet."), ("Answer", "Kung ang nanay niyo po ay animnapung taon pataas, hindi PhilHealth member, hindi po siya pensioner, puwede niyo po siyang gamitin as dependent n’yo yung magulang ninyo.", "If your mother is sixty years and above, not a PhilHealth member, and not a pensioner, you can use your parent as your dependent.")]
_L10B = [("Question", "Ang anak ko ay na-ospital, na-dengue. Walong libong piso po lang ang covered. Ang bill po namin ay pitong libo, limang daan at walumpu’t tatlong piso. Halos lahat ng gamot, kami ang bumili. Tapos nagbayad pa kami ng professional fee na isang libo at anim na raang piso, bukod sa nakalistang dalawang libo at apat na raang piso na billing namin. Walong libong piso lang daw po ba talaga ang covered sa Dengue?", "My child was hospitalized with dengue. Only 8,000 pesos is covered. Our bill is 7,583 pesos. We bought almost all the medicine. Then we also paid a professional fee of 1,600 pesos, aside from our listed billing of 2,400 pesos. Is it really only 8,000 pesos that is covered for Dengue?"), ("Answer", "Opo. Ito po ay pakete yung sa Dengue isa po natin na tinatawag, walong libong piso po ang ating benepisyo. At kung ito naman yung tinatawag nating Dengue dalawa, ito po yung mas matindi o yung may mga kumplikasyon na, labing-anim na libong piso po yung ating pakete para diyan.", "Yes. That is the package for what we call Dengue 1, our benefit is 8,000 pesos. And what we call Dengue 2, which is the more severe one or the one with complications, our package for that is 16,000 pesos.")]
_K10 = [("Passage 1 (the book’s gist)", "An OFW who had been working overseas for 8 years now would like to know if his or her mom could use his or her Philhealth. The interviewee said if the mom’s age is 60 and above and she is not a Philhealth member and not a pensioner, the mom could use the OFW’s Philhealth as a dependent."), ("Passage 2 (the book’s gist)", "A mom whose child was hospitalized for dengue is asking if Philhealth only covers Php8,000.00 for dengue cases. She said she spent more than the coverage. The interviewee said that the Dengue 1 package covers Php8,000 of expenses and the Dengue 2 package covers Php16,000.")]
_SP = [("Caller", "Magandang umaga po. Self-employed po ako. Gusto ko pong malaman kung paano magparehistro sa PhilHealth.", "Good morning. I am self-employed. I would like to know how to register with PhilHealth."), ("Operator", "Magandang umaga po. Kailangan lang po ninyong punan ang Member Registration Form at isumite ito sa PhilHealth.", "Good morning. You only need to fill up the Member Registration Form and submit it to PhilHealth."), ("Caller", "Magkano po ang kailangan kong bayaran buwan-buwan?", "How much do I need to pay every month?"), ("Operator", "Depende po iyan sa inyong kita. Tatawagan ko po kayo ng detalye.", "That depends on your income. I will give you the details."), ("Caller", "Anu-ano po ang mga benepisyo ko?", "What are my benefits?"), ("Operator", "May pakete po ng benepisyo mula sa simple hanggang sa komplikadong sakit.", "There is a package of benefits from simple to complicated illnesses."), ("Caller", "Maraming salamat po.", "Thank you very much."), ("Operator", "Walang anuman po.", "You’re welcome.")]
